<script>
(function(){
'use strict';
var TAU = Math.PI*2;
function ss(a,b,x){var t=(x-a)/(b-a); t=t<0?0:(t>1?1:t); return t*t*(3-2*t);}

/* ============================================================
   1. HEIGHT-FIELD TEXTURE GENERATION (procedural, offscreen 2D)
   ============================================================ */
function blurArr(src,size,r){
  if(r<1) return src;
  var tmp=new Float32Array(size*size), out=new Float32Array(size*size);
  var norm=1/(2*r+1), x,y,i,sum,row,xa,xb;
  for(y=0;y<size;y++){
    row=y*size; sum=0;
    for(i=-r;i<=r;i++){ var xi=i<0?0:(i>size-1?size-1:i); sum+=src[row+xi]; }
    for(x=0;x<size;x++){
      tmp[row+x]=sum*norm;
      xa=x-r; if(xa<0)xa=0;
      xb=x+r+1; if(xb>size-1)xb=size-1;
      sum+=src[row+xb]-src[row+xa];
    }
  }
  for(x=0;x<size;x++){
    sum=0;
    for(i=-r;i<=r;i++){ var yi=i<0?0:(i>size-1?size-1:i); sum+=tmp[yi*size+x]; }
    for(y=0;y<size;y++){
      out[y*size+x]=sum*norm;
      var ya=y-r; if(ya<0)ya=0;
      var yb=y+r+1; if(yb>size-1)yb=size-1;
      sum+=tmp[yb*size+x]-tmp[ya*size+x];
    }
  }
  return out;
}
function buildTex(size, drawFn, r1, r2){
  var cv=document.createElement('canvas'); cv.width=size; cv.height=size;
  var c=cv.getContext('2d',{willReadFrequently:true});
  drawFn(c,size);
  var d=c.getImageData(0,0,size,size).data;
  var n=size*size, h=new Float32Array(n), i;
  for(i=0;i<n;i++) h[i]=d[i<<2]/255;
  h=blurArr(h,size,r1); h=blurArr(h,size,r2);
  var hu=new Float32Array(n), hv=new Float32Array(n), x,y;
  for(y=0;y<size;y++){
    var row=y*size, rowU=(y>0?y-1:0)*size, rowD=(y<size-1?y+1:size-1)*size;
    for(x=0;x<size;x++){
      var xl=x>0?x-1:0, xr=x<size-1?x+1:size-1;
      hu[row+x]=(h[row+xr]-h[row+xl])*0.5;
      hv[row+x]=(h[rowD+x]-h[rowU+x])*0.5;
    }
  }
  return {size:size,h:h,hu:hu,hv:hv};
}

/* ---- drawing helpers (grey level == relief height) ---- */
function fillDisc(c,x,y,r,col){c.beginPath();c.arc(x,y,r,0,TAU);c.fillStyle=col;c.fill();}
function ring(c,x,y,r,w,col){c.beginPath();c.arc(x,y,r,0,TAU);c.lineWidth=w;c.strokeStyle=col;c.stroke();}
function poly(c,x,y,r,n,rot){c.beginPath();for(var i=0;i<n;i++){var a=rot+i/n*TAU,px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;if(i)c.lineTo(px,py);else c.moveTo(px,py);}c.closePath();}
function starPath(c,x,y,r,pts,inner,rot){
  c.beginPath();
  for(var i=0;i<pts*2;i++){
    var rr=(i%2)?r*inner:r, a=rot+i*Math.PI/pts;
    var px=x+Math.cos(a)*rr, py=y+Math.sin(a)*rr;
    if(i)c.lineTo(px,py);else c.moveTo(px,py);
  }
  c.closePath();
}
function arcText(c,text,cx,cy,r,mid,size,flip,fill){
  c.save(); c.fillStyle=fill; c.textAlign='center'; c.textBaseline='middle';
  c.font='bold '+size.toFixed(2)+'px Georgia,"Times New Roman",serif';
  var w=[],total=0,i;
  for(i=0;i<text.length;i++){var ww=c.measureText(text[i]).width; w.push(ww); total+=ww;}
  var track=size*0.10;
  total+=track*(text.length-1);
  var dir=flip?-1:1, ang=mid-dir*(total/r)/2;
  for(i=0;i<text.length;i++){
    ang+=dir*(w[i]/r)/2;
    c.save();
    c.translate(cx+Math.cos(ang)*r, cy+Math.sin(ang)*r);
    c.rotate(ang+(flip?-Math.PI/2:Math.PI/2));
    c.fillText(text[i],0,0);
    c.restore();
    ang+=dir*(w[i]/r)/2+dir*(track/r);
  }
  c.restore();
}
function spacedText(c,text,cx,cy,font,sp,fill){
  c.save(); c.font=font; c.fillStyle=fill; c.textAlign='center'; c.textBaseline='middle';
  var w=[],total=0,i;
  for(i=0;i<text.length;i++){var ww=c.measureText(text[i]).width;w.push(ww);total+=ww+sp;}
  total-=sp;
  var x=cx-total/2;
  for(i=0;i<text.length;i++){c.fillText(text[i],x+w[i]/2,cy);x+=w[i]+sp;}
  c.restore();
}
function fitFill(c,text,cx,cy,maxW,font,fill){
  c.save(); c.font=font; c.fillStyle=fill; c.textAlign='center'; c.textBaseline='middle';
  var w=c.measureText(text).width, k=w>maxW?maxW/w:1;
  c.translate(cx,cy); c.scale(k,1); c.fillText(text,0,0); c.restore();
}

/* ---- shared rim / collar ---- */
function drawCollar(c,S){
  var R=S/2, cc=S/2, i,a;
  c.fillStyle='#000'; c.fillRect(0,0,S,S);
  fillDisc(c,cc,cc,R*0.999,'#565656');           /* field */
  ring(c,cc,cc,R*0.945,R*0.085,'#f5f5f5');       /* raised rim */
  ring(c,cc,cc,R*0.9905,R*0.019,'#909090');      /* rim edge shoulder */
  ring(c,cc,cc,R*0.884,R*0.030,'#0d0d0d');       /* groove */
  for(i=0;i<76;i++){                              /* bead circle */
    a=i/76*TAU;
    fillDisc(c,cc+Math.cos(a)*R*0.845,cc+Math.sin(a)*R*0.845,R*0.0155,'#efefef');
  }
}
/* ---- OBVERSE: mint emblem in raised relief ---- */
function drawFront(c,S){
  var R=S/2, cc=S/2, i,a;
  drawCollar(c,S);
  arcText(c,'WASTEDTOKEN MINT',cc,cc,R*0.780,-Math.PI/2,R*0.112,false,'#ffffff');
  arcText(c,'CHALLENGE COIN',cc,cc,R*0.782,Math.PI/2,R*0.100,true,'#ffffff');
  /* side ornaments */
  for(i=-1;i<=1;i+=2){
    starPath(c,cc+i*R*0.78,cc,R*0.045,5,0.44,-Math.PI/2);
    c.fillStyle='#ffffff'; c.fill();
  }
  /* inner recessed panel */
  fillDisc(c,cc,cc,R*0.672,'#343434');
  ring(c,cc,cc,R*0.672,R*0.018,'#ededed');
  ring(c,cc,cc,R*0.640,R*0.008,'#111111');
  /* engine-turned sunburst */
  c.save(); c.translate(cc,cc);
  for(i=0;i<48;i++){
    a=i/48*TAU;
    var w=0.026;
    c.beginPath();
    c.moveTo(Math.cos(a)*R*0.19, Math.sin(a)*R*0.19);
    c.lineTo(Math.cos(a+w)*R*0.615, Math.sin(a+w)*R*0.615);
    c.lineTo(Math.cos(a-w)*R*0.615, Math.sin(a-w)*R*0.615);
    c.closePath();
    c.fillStyle=(i%2)?'#8e8e8e':'#454545';
    c.fill();
  }
  c.restore();
  /* hexagon shield */
  poly(c,cc,cc,R*0.50,6,-Math.PI/2); c.fillStyle='#5f5f5f'; c.fill();
  poly(c,cc,cc,R*0.50,6,-Math.PI/2); c.lineWidth=R*0.045; c.strokeStyle='#fdfdfd'; c.stroke();
  poly(c,cc,cc,R*0.425,6,-Math.PI/2); c.lineWidth=R*0.014; c.strokeStyle='#161616'; c.stroke();
  /* monogram W */
  fitFill(c,'W',cc,cc+R*0.03,R*0.60,'bold '+(R*0.60).toFixed(1)+'px Georgia,"Times New Roman",serif','#ffffff');
  /* three beads above monogram */
  for(i=-1;i<=1;i++) fillDisc(c,cc+i*R*0.085,cc-R*0.315,R*0.021,'#ffffff');
  spacedText(c,'MINT',cc,cc+R*0.375,'bold '+(R*0.072).toFixed(1)+'px Georgia,serif',R*0.028,'#f2f2f2');
}
/* ---- REVERSE: denomination ---- */
function drawBack(c,S,denom){
  var R=S/2, cc=S/2, i;
  drawCollar(c,S);
  arcText(c,'WASTEDTOKEN MINT',cc,cc,R*0.785,-Math.PI/2,R*0.100,false,'#ffffff');
  arcText(c,'SERIES I  MMXXV',cc,cc,R*0.788,Math.PI/2,R*0.092,true,'#ffffff');
  for(i=-1;i<=1;i+=2){
    starPath(c,cc+i*R*0.785,cc,R*0.040,4,0.40,0);
    c.fillStyle='#ffffff'; c.fill();
  }
  fillDisc(c,cc,cc,R*0.700,'#313131');
  ring(c,cc,cc,R*0.700,R*0.016,'#e2e2e2');
  /* faint concentric turning */
  for(i=0;i<13;i++) ring(c,cc,cc,R*(0.665-i*0.048),R*0.013,(i%2)?'#3e3e3e':'#2b2b2b');
  /* rules */
  c.fillStyle='#f0f0f0';
  c.fillRect(cc-R*0.44,cc-R*0.335,R*0.88,R*0.020);
  c.fillRect(cc-R*0.30,cc-R*0.295,R*0.60,R*0.012);
  c.fillRect(cc-R*0.44,cc+R*0.375,R*0.88,R*0.020);
  /* denomination */
  fitFill(c,denom,cc,cc-R*0.055,R*1.06,'bold '+(R*0.40).toFixed(1)+'px Georgia,"Times New Roman",serif','#ffffff');
  spacedText(c,'TOKENS',cc,cc+R*0.215,'bold '+(R*0.135).toFixed(1)+'px Georgia,serif',R*0.055,'#ffffff');
  /* small stars row */
  for(i=-1;i<=1;i++){ starPath(c,cc+i*R*0.115,cc+R*0.520,R*0.032,5,0.44,-Math.PI/2); c.fillStyle='#f4f4f4'; c.fill(); }
}

/* ============================================================
   2. COIN RAY-TRACED RENDERER (per-pixel, deterministic)
   ============================================================ */
/* world lights */
function nrm3(v){var l=Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);return [v[0]/l,v[1]/l,v[2]/l];}
var L1=nrm3([-0.52,0.70,0.52]), L2=nrm3([0.84,0.24,0.52]), L3=nrm3([0.06,-0.90,0.44]);
var L1x=L1[0],L1y=L1[1],L1z=L1[2],L2x=L2[0],L2y=L2[1],L2z=L2[2],L3x=L3[0],L3y=L3[1],L3z=L3[2];

function createCoin(canvas,cfg){
  var ctx=canvas.getContext('2d');
  var D=cfg.camD||7, HH=cfg.thick||0.115, REEDS=cfg.reeds||96, fit=cfg.fit||0.325;
  var bump=cfg.bump||3.3, rmul=(cfg.rmul==null?1:cfg.rmul), radd=cfg.radd||0, specMul=cfg.specMul||1;
  var expo=cfg.expo||1;
  var bcR=cfg.color[0],bcG=cfg.color[1],bcB=cfg.color[2];
  var texF=cfg.front, texB=cfg.back;
  var W=0,H=0,img=null,data=null,bg=null,mask=null,S=1,cx=0,cy=0;
  var m00=1,m01=0,m02=0,m10=0,m11=1,m12=0,m20=0,m21=0,m22=1,ox=0,oy=0,oz=D;
  var oR=0,oG=0,oB=0,tH=0,tU=0,tV=0;

  function buildBG(){
    bg=new Uint8ClampedArray(W*H*4);
    for(var y=0;y<H;y++){
      for(var x=0;x<W;x++){
        var u=(x-cx)/(0.5*W), v=(y-cy)/(0.5*H);
        var d=Math.sqrt(u*u+v*v);
        var g=y/H;
        var r=7+9*(1-g), gg=8+10*(1-g), b=12+15*(1-g);
        var gl=Math.max(0,1-d/1.25); gl=Math.pow(gl,2.6)*(cfg.glow==null?17:cfg.glow);
        r+=gl; gg+=gl*0.80; b+=gl*0.52;
        var p=(y*W+x)*4;
        bg[p]=r; bg[p+1]=gg; bg[p+2]=b; bg[p+3]=255;
      }
    }
  }
  function resize(px,py){
    W=px; H=py; canvas.width=W; canvas.height=H;
    img=ctx.createImageData(W,H); data=img.data;
    S=fit*Math.min(W,H)*D; cx=W/2; cy=H/2;
    mask=new Uint8Array(W*H);
    buildBG();
  }
  function sampleTex(t,u,v){
    var s=t.size, fx=u*(s-1), fy=v*(s-1);
    if(fx<0)fx=0; else if(fx>s-1)fx=s-1;
    if(fy<0)fy=0; else if(fy>s-1)fy=s-1;
    var x0=fx|0, y0=fy|0, x1=x0+1<s?x0+1:s-1, y1=y0+1<s?y0+1:s-1;
    var ax=fx-x0, ay=fy-y0;
    var i00=y0*s+x0,i10=y0*s+x1,i01=y1*s+x0,i11=y1*s+x1;
    var w00=(1-ax)*(1-ay), w10=ax*(1-ay), w01=(1-ax)*ay, w11=ax*ay;
    tH=t.h[i00]*w00+t.h[i10]*w10+t.h[i01]*w01+t.h[i11]*w11;
    tU=t.hu[i00]*w00+t.hu[i10]*w10+t.hu[i01]*w01+t.hu[i11]*w11;
    tV=t.hv[i00]*w00+t.hv[i10]*w10+t.hv[i01]*w01+t.hv[i11]*w11;
  }
  function aces(x){
    x*=0.88*expo;
    var y=(x*(2.51*x+0.03))/(x*(2.43*x+0.59)+0.14);
    return y<0?0:(y>1?1:y);
  }
  function shade(nx,ny,nz,vx,vy,vz,rough,occ){
    var ndv=nx*vx+ny*vy+nz*vz;
    if(ndv<0){nx=-nx;ny=-ny;nz=-nz;ndv=-ndv;}
    if(ndv<0.02)ndv=0.02;
    var rx=2*ndv*nx-vx, ry=2*ndv*ny-vy, rz=2*ndv*nz-vz;
    var q=1-rough, blobExp=6+120*q*q;
    /* studio environment */
    var tf=ss(-0.42,0.95,ry);
    var er=0.040+0.30*tf, eg=0.046+0.325*tf, eb=0.068+0.40*tf;
    var df=ss(-0.10,-0.95,ry);
    er+=0.115*df; eg+=0.058*df; eb+=0.026*df;
    var band=Math.exp(-Math.abs(ry-0.10)*11)*0.30;
    er+=band; eg+=band*0.97; eb+=band*0.93;
    var d1=rx*L1x+ry*L1y+rz*L1z;
    if(d1>0){var b1=Math.pow(d1,blobExp)*3.4; er+=b1; eg+=b1*0.95; eb+=b1*0.84;}
    var d2=rx*L2x+ry*L2y+rz*L2z;
    if(d2>0){var b2=Math.pow(d2,blobExp*0.65)*1.5; er+=b2*0.58; eg+=b2*0.74; eb+=b2*1.0;}
    var d3=rx*L3x+ry*L3y+rz*L3z;
    if(d3>0){var b3=Math.pow(d3,blobExp*0.45)*0.75; er+=b3; eg+=b3*0.58; eb+=b3*0.28;}
    /* Fresnel-tinted metal reflectance */
    var fr=1-ndv; fr=fr*fr*fr*fr*fr;
    var Fr=bcR+(1-bcR)*fr, Fg=bcG+(1-bcG)*fr, Fb=bcB+(1-bcB)*fr;
    /* tight raking highlights */
    var se=18+1000*q*q*q, sR=0,sG=0,sB=0,hx,hy,hz,hl,nh,sp;
    hx=L1x+vx; hy=L1y+vy; hz=L1z+vz; hl=1/Math.sqrt(hx*hx+hy*hy+hz*hz);
    nh=nx*hx*hl+ny*hy*hl+nz*hz*hl;
    if(nh>0){sp=Math.pow(nh,se)*3.0*specMul; sR+=sp; sG+=sp*0.94; sB+=sp*0.82;}
    hx=L2x+vx; hy=L2y+vy; hz=L2z+vz; hl=1/Math.sqrt(hx*hx+hy*hy+hz*hz);
    nh=nx*hx*hl+ny*hy*hl+nz*hz*hl;
    if(nh>0){sp=Math.pow(nh,se*0.8)*1.3*specMul; sR+=sp*0.62; sG+=sp*0.76; sB+=sp*1.0;}
    var cr=er*Fr*occ+sR*Fr+bcR*0.05;
    var cg=eg*Fg*occ+sG*Fg+bcG*0.05;
    var cb=eb*Fb*occ+sB*Fb+bcB*0.05;
    oR=Math.sqrt(aces(cr)); oG=Math.sqrt(aces(cg)); oB=Math.sqrt(aces(cb));
  }
  function trace(sx,sy){
    var dx=(sx-cx)/S, dy=-(sy-cy)/S, dz=-1;
    var il=1/Math.sqrt(dx*dx+dy*dy+1); dx*=il; dy*=il; dz*=il;
    var ddx=m00*dx+m10*dy+m20*dz;
    var ddy=m01*dx+m11*dy+m21*dz;
    var ddz=m02*dx+m12*dy+m22*dz;
    var best=1e18, type=0, tt,X,Y,Z;
    if(ddz>1e-12||ddz<-1e-12){
      tt=(HH-oz)/ddz;
      if(tt>0){X=ox+tt*ddx;Y=oy+tt*ddy; if(X*X+Y*Y<=1){best=tt;type=1;}}
      tt=(-HH-oz)/ddz;
      if(tt>0&&tt<best){X=ox+tt*ddx;Y=oy+tt*ddy; if(X*X+Y*Y<=1){best=tt;type=2;}}
    }
    var A=ddx*ddx+ddy*ddy;
    if(A>1e-14){
      var B=2*(ox*ddx+oy*ddy), C=ox*ox+oy*oy-1, disc=B*B-4*A*C;
      if(disc>0){
        var sq=Math.sqrt(disc), got=false;
        tt=(-B-sq)/(2*A);
        if(tt>0&&tt<best){Z=oz+tt*ddz; if(Z>=-HH&&Z<=HH){best=tt;type=3;got=true;}}
        if(!got){
          tt=(-B+sq)/(2*A);
          if(tt>0&&tt<best){Z=oz+tt*ddz; if(Z>=-HH&&Z<=HH){best=tt;type=3;}}
        }
      }
    }
    if(!type) return 0;
    X=ox+best*ddx; Y=oy+best*ddy; Z=oz+best*ddz;
    var nx,ny,nz,rough,occ;
    if(type===3){
      var phi=Math.atan2(Y,X), rd=REEDS*phi;
      var nt=0.46*Math.sin(rd);
      nx=X-nt*Y; ny=Y+nt*X; nz=0;
      var az=Z/HH, aa=az<0?-az:az;
      if(aa>0.60){
        var w=(aa-0.60)/0.40, w2=w*w;
        nz+=(az>0?1:-1)*w2*2.0;
        var k=1-0.42*w2; nx*=k; ny*=k;
      }
      rough=0.19*rmul+radd;
      occ=0.80+0.20*(0.5+0.5*Math.cos(rd));
    }else{
      var isF=(type===1), tex=isF?texF:texB;
      var u=isF?(0.5+0.5*X):(0.5-0.5*X), v=0.5-0.5*Y;
      sampleTex(tex,u,v);
      if(isF){nx=-bump*tU; ny=bump*tV; nz=1;}
      else{nx=bump*tU; ny=bump*tV; nz=-1;}
      var r2=X*X+Y*Y, r=Math.sqrt(r2);
      if(r>1e-4){
        var lp=0.020*Math.sin(r*110);
        nx+=lp*X/r; ny+=lp*Y/r;
        if(r>0.952){
          var ww=(r-0.952)/0.048, ww2=ww*ww*1.7;
          nx+=ww2*1.35*X/r; ny+=ww2*1.35*Y/r;
          var kz=1-0.55*ww2; if(kz<0.06)kz=0.06; nz*=kz;
        }
      }
      rough=(0.215-0.118*tH)*rmul+radd;
      occ=0.50+0.50*tH;
    }
    if(rough<0.03)rough=0.03; if(rough>0.5)rough=0.5;
    var nl=1/Math.sqrt(nx*nx+ny*ny+nz*nz); nx*=nl; ny*=nl; nz*=nl;
    var wnx=m00*nx+m01*ny+m02*nz, wny=m10*nx+m11*ny+m12*nz, wnz=m20*nx+m21*ny+m22*nz;
    shade(wnx,wny,wnz,-dx,-dy,-dz,rough,occ);
    return 1;
  }
  function render(t){
    if(!data) return;
    t=t-Math.floor(t);
    var yaw=cfg.yaw(t), pit=cfg.pitch(t);
    var cy_=Math.cos(yaw), sy_=Math.sin(yaw), cp=Math.cos(pit), sp=Math.sin(pit);
    m00=cy_; m01=0; m02=sy_;
    m10=sp*sy_; m11=cp; m12=-sp*cy_;
    m20=-cp*sy_; m21=sp; m22=cp*cy_;
    ox=D*m20; oy=D*m21; oz=D*m22;
    data.set(bg);
    /* exact silhouette bbox from both cap rims */
    var minx=1e9,maxx=-1e9,miny=1e9,maxy=-1e9,i,k;
    for(i=0;i<64;i++){
      var a=i/64*TAU, ca=Math.cos(a), sa=Math.sin(a);
      for(k=0;k<2;k++){
        var z=k?HH:-HH;
        var wx=m00*ca+m01*sa+m02*z, wy=m10*ca+m11*sa+m12*z, wz=m20*ca+m21*sa+m22*z;
        var dep=D-wz; if(dep<0.2) continue;
        var px=cx+S*wx/dep, py=cy-S*wy/dep;
        if(px<minx)minx=px; if(px>maxx)maxx=px;
        if(py<miny)miny=py; if(py>maxy)maxy=py;
      }
    }
    var x0=Math.max(0,Math.floor(minx)-3), x1=Math.min(W-1,Math.ceil(maxx)+3);
    var y0=Math.max(0,Math.floor(miny)-3), y1=Math.min(H-1,Math.ceil(maxy)+3);
    var px2,py2,idx,p;
    for(py2=y0;py2<=y1;py2++){
      for(px2=x0;px2<=x1;px2++){
        idx=py2*W+px2;
        if(trace(px2+0.5,py2+0.5)){
          mask[idx]=1; p=idx*4;
          data[p]=oR*255; data[p+1]=oG*255; data[p+2]=oB*255; data[p+3]=255;
        } else mask[idx]=0;
      }
    }
    /* silhouette anti-aliasing */
    for(py2=y0+1;py2<y1;py2++){
      for(px2=x0+1;px2<x1;px2++){
        idx=py2*W+px2;
        var m=mask[idx];
        if(m===mask[idx-1]&&m===mask[idx+1]&&m===mask[idx-W]&&m===mask[idx+W]) continue;
        var ar=0,ag=0,ab=0;
        for(k=0;k<4;k++){
          var sxx=px2+((k&1)?0.72:0.28), syy=py2+((k&2)?0.72:0.28);
          if(trace(sxx,syy)){ar+=oR;ag+=oG;ab+=oB;}
          else{p=idx*4; ar+=bg[p]/255; ag+=bg[p+1]/255; ab+=bg[p+2]/255;}
        }
        p=idx*4;
        data[p]=ar*63.75; data[p+1]=ag*63.75; data[p+2]=ab*63.75; data[p+3]=255;
      }
    }
    ctx.putImageData(img,0,0);
  }
  return {resize:resize,render:render,canvas:canvas};
}

/* ============================================================
   3. BUILD TEXTURES + SCENES
   ============================================================ */
var TEX_FRONT = buildTex(512, drawFront, 4, 2);
var TEX_BACK_HERO = buildTex(512, function(c,S){drawBack(c,S,'10,000');}, 4, 2);

var heroCanvas=document.getElementById('coin-hero');
var hero=createCoin(heroCanvas,{
  color:[1.00,0.775,0.395], front:TEX_FRONT, back:TEX_BACK_HERO,
  thick:0.118, reeds:96, fit:0.325, bump:3.5, glow:18, expo:1.02,
  yaw:function(t){return TAU*t+0.15;},
  pitch:function(t){return 2*TAU*t+0.22;}
});

var EDITIONS=[
  {key:'bronze', denom:'1,000',  color:[0.815,0.500,0.290], rmul:1.06, radd:0.01, expo:1.06, glow:14},
  {key:'silver', denom:'5,000',  color:[0.955,0.960,0.985], rmul:0.86, radd:0.00, expo:0.96, glow:15},
  {key:'gold',   denom:'10,000', color:[1.000,0.760,0.350], rmul:0.95, radd:0.00, expo:1.02, glow:16},
  {key:'black',  denom:'25,000', color:[0.165,0.180,0.215], rmul:0.42, radd:0.00, expo:1.35, glow:12, specMul:1.7}
];
var edRenderers=[];
(function initEditions(){
  var tiles=document.querySelectorAll('.edition');
  for(var i=0;i<tiles.length;i++){
    var tile=tiles[i], key=tile.getAttribute('data-edition');
    var spec=null;
    for(var j=0;j<EDITIONS.length;j++) if(EDITIONS[j].key===key) spec=EDITIONS[j];
    if(!spec) continue;
    var cvs=tile.querySelector('.edition-canvas');
    var back=buildTex(320,(function(d){return function(c,S){drawBack(c,S,d);};})(spec.denom),3,1);
    var ph=i*0.19;
    var r=createCoin(cvs,{
      color:spec.color, front:TEX_FRONT, back:back,
      thick:0.118, reeds:88, fit:0.315, bump:3.2,
      rmul:spec.rmul, radd:spec.radd, expo:spec.expo, glow:spec.glow, specMul:spec.specMul||1,
      yaw:function(t){return TAU*t;},
      pitch:function(t){return 0.30*Math.sin(TAU*t)+0.16;}
    });
    edRenderers.push({r:r,phase:ph,visible:true,canvas:cvs});
  }
})();

/* ============================================================
   4. SIZING + ANIMATION LOOP + PUBLIC API
   ============================================================ */
var HERO_MAX=480, ED_MAX=260;
function fitOne(rend,maxRes){
  var w=rend.canvas.clientWidth||300;
  var dpr=Math.min(window.devicePixelRatio||1,2);
  var px=Math.round(Math.min(maxRes,Math.max(150,w*dpr)));
  rend.resize(px,px);
}
function fitAll(){
  fitOne(hero,HERO_MAX);
  for(var i=0;i<edRenderers.length;i++) fitOne(edRenderers[i].r,ED_MAX);
}
fitAll();

var running=true, rafId=0, t0=performance.now(), lastT=0, edIdx=0, lastEd=0;
var HERO_LOOP=10000, ED_LOOP=15000;
var frames=0, acc=0, downgraded=0;

function frame(now){
  if(!running) return;
  var tt=((now-t0)/HERO_LOOP)%1;
  var s=performance.now();
  lastT=tt;
  hero.render(tt);
  acc+=performance.now()-s; frames++;
  if(frames===36){
    var avg=acc/frames; frames=0; acc=0;
    if(avg>27&&downgraded<2){ downgraded++; HERO_MAX=Math.round(HERO_MAX*0.8); fitOne(hero,HERO_MAX); }
  }
  if(now-lastEd>60&&edRenderers.length){
    lastEd=now;
    var tries=0;
    while(tries<edRenderers.length){
      var e=edRenderers[edIdx%edRenderers.
